const Icon = ({
  className,
  name,
  fill,
  width = 24,
  height = 24,
  size = 24,
  children,
  ...props
}) => {
  const iconSet = size === 20 ? icons20 : icons;
  const actualWidth = size === 20 ? 20 : width;
  const actualHeight = size === 20 ? 20 : height;

  return (
    <svg
      className={cn("inline-flex size-6", className)}
      width={actualWidth}
      height={actualHeight}
      viewBox={`0 0 ${actualWidth} ${actualHeight}`}
      {...props}
    >
      <title>{name}</title>
      <path fill={fill} d={iconSet[name]} />
      {children}
    </svg>
  );
};

export default Icon;
